CREATE VIEW cdn.CrmTerminarzOperatoraView(RodzajWydarzenia,KodOpiekuna,Realizacja,Calodzienne,IdZrodla,Tytul,Opis,TerminOd,TerminDo,Status,Reminder,OpiekunTyp,OpiekunId,NumerDokumentu,Kontrahent,Priorytet,ZadanieCykliczne,Uczestnicy) AS SELECT 700,CASE CrK_OpiekunTyp WHEN 8 THEN CASE CrK_OpiekunId WHEN 0 THEN '' WHEN 1 THEN 'ADMIN' WHEN 12 THEN 'BARTEK' WHEN 3 THEN 'DAREK' WHEN 10 THEN 'GOSIA' WHEN 14 THEN 'JAREK' WHEN 5 THEN 'KRZYSZTOF' WHEN 4 THEN 'LESZEK' WHEN 8 THEN 'LIDIA' WHEN 6 THEN 'MACIEJ' WHEN 9 THEN 'MAGDA' WHEN 11 THEN 'MAGDALENA' WHEN 7 THEN 'MAŁGORZATA' WHEN 13 THEN 'ONE_DOD' END ELSE IsNull((SELECT TOP 1 PRI_Kod FROM cdn.PracIdx WHERE PRI_PraID=CrK_OpiekunId), '') END,CASE When CRK_Bufor=1 Then 2 ELSE 1 END,0,CRK_CRKId,Case CRK_Temat When '' Then RTrim(Convert(VarChar(50), CRK_Opis)) Else RTrim(Convert (VarChar(50), CRK_Temat)) End,RTrim(Convert (VarChar(100), CRK_Opis)),CRK_TerminOd,CRK_TerminDo,Case When CRK_Bufor=0 Then 1 When CRK_Bufor=1 AND IsNull(CRK_ParId, 0)=0 Then 2 When CRK_Bufor=1 AND IsNull(CRK_ParId, 0)>0 Then 3 Else 0 End ,CASE WHEN CrK_Przypomnienie=1 Then '<Reminders><Reminder AlertTime="' + Convert(VarChar(20), CrK_CzasPrzypomnienia) + '" TimeBeforeStart="' + CDN.TimeDiff(CrK_CzasPrzypomnienia, CrK_TerminOd) + '"/></Reminders>' Else SPACE(100) End,CRK_OpiekunTyp,CRK_OpiekunID,CRK_NumerPelny,Pod_Kod,CRK_Priorytet,0 As ZadanieCykliczne,(SELECT '<ResourceIds>' + STUFF( (SELECT   CHAR(10) + '<ResourceId Type="System.String" Value="' +  b.CrU_Akronim + '" /> '  FROM cdn.CrmUczestnicy b WHERE CrU_CrKId = CrK_CrKId FOR XML PATH(''),TYPE).value('(./text())[1]','NVARCHAR(MAX)'), 1,1,'')	+ '</ResourceIds>') FROM CDN.CRMKontakty JOIN CDN.PodmiotyView ON Pod_PodId = CrK_PodId AND Pod_PodmiotTyp = CrK_PodmiotTyp WHERE CRK_Zadanie = 1 And CRK_Bufor > -1 AND CRK_CYKL = 0 UNION ALL SELECT 700,CASE CrK_OpiekunTyp WHEN 8 THEN CASE CrK_OpiekunId WHEN 0 THEN '' WHEN 1 THEN 'ADMIN' WHEN 12 THEN 'BARTEK' WHEN 3 THEN 'DAREK' WHEN 10 THEN 'GOSIA' WHEN 14 THEN 'JAREK' WHEN 5 THEN 'KRZYSZTOF' WHEN 4 THEN 'LESZEK' WHEN 8 THEN 'LIDIA' WHEN 6 THEN 'MACIEJ' WHEN 9 THEN 'MAGDA' WHEN 11 THEN 'MAGDALENA' WHEN 7 THEN 'MAŁGORZATA' WHEN 13 THEN 'ONE_DOD' END ELSE IsNull((SELECT TOP 1 PRI_Kod FROM cdn.PracIdx WHERE PRI_PraID=CrK_OpiekunId), '') END,CASE When CRK_Bufor=1 Then 2 ELSE 1 END,0,CRK_CRKId,Case CRK_Temat When '' Then RTrim(Convert(VarChar(50), CRK_Opis)) Else RTrim(Convert (VarChar(50), CRK_Temat)) End,RTrim(Convert (VarChar(100), CRK_Opis)),CRC_TerminOd AS CRK_TerminOd,CRC_TerminDo AS CRK_TerminDo,Case When CRK_Bufor=0 Then 1 When CRK_Bufor=1 AND IsNull(CRK_ParId, 0)=0 Then 2 When CRK_Bufor=1 AND IsNull(CRK_ParId, 0)>0 Then 3 Else 0 End ,CASE WHEN CrC_Przypomnienie=1 Then '<Reminders><Reminder AlertTime="' + Convert(VarChar(20), CrC_CzasPrzypomnienia) + '" TimeBeforeStart="' + CDN.TimeDiff(CrC_CzasPrzypomnienia, CRC_TerminOd) + '"/></Reminders>' Else SPACE(100) End,CRK_OpiekunTyp,CRK_OpiekunID,CRK_NumerPelny,Pod_Kod,CRK_Priorytet,CrC_CrCId As ZadanieCykliczne,(SELECT '<ResourceIds>' + STUFF( (SELECT   CHAR(10) + '<ResourceId Type="System.String" Value="' +  b.CrU_Akronim + '" /> '  FROM cdn.CrmUczestnicy b WHERE CrU_CrKId = CrK_CrKId FOR XML PATH(''),TYPE).value('(./text())[1]','NVARCHAR(MAX)'), 1,1,'')	+ '</ResourceIds>') FROM CDN.CRMKontakty LEFT JOIN CDN.CrmKontaktyCykl ON CrC_CrKId = CrK_CrKId AND CRC_Bufor = 1 AND CRC_Aktywny = 1 JOIN CDN.PodmiotyView ON Pod_PodId = CrK_PodId AND Pod_PodmiotTyp = CrK_PodmiotTyp WHERE CRK_Zadanie = 1 And CRK_Bufor > -1 And CRK_CYKL = 1 AND CRC_CRCID IS NOT NULL UNION ALL SELECT 900,CASE SrY_SerwisantTyp WHEN 8 THEN CASE SrY_SerwisantID WHEN 0 THEN '' WHEN 1 THEN 'ADMIN' WHEN 12 THEN 'BARTEK' WHEN 3 THEN 'DAREK' WHEN 10 THEN 'GOSIA' WHEN 14 THEN 'JAREK' WHEN 5 THEN 'KRZYSZTOF' WHEN 4 THEN 'LESZEK' WHEN 8 THEN 'LIDIA' WHEN 6 THEN 'MACIEJ' WHEN 9 THEN 'MAGDA' WHEN 11 THEN 'MAGDALENA' WHEN 7 THEN 'MAŁGORZATA' WHEN 13 THEN 'ONE_DOD' END ELSE IsNull((SELECT TOP 1 PRI_Kod FROM cdn.PracIdx WHERE PRI_PraID=SrY_SerwisantID), '') END,CASE When SrY_Zakonczona=0 Then 2 ELSE 1 END,0,SrY_SrYId,Convert (VarChar(50),  SrY_TwrNazwa),Convert (VarChar(100), SrY_Opis),SrY_TerminOd,SrY_TerminDo,Case When SrY_Zakonczona=1 Then 5 Else 4 End,Case When SrY_Przypomnienie=1 Then '<Reminders><Reminder AlertTime="' + Convert(VarChar(20),SrY_CzasPrzypomnienia) + '" TimeBeforeStart="' + CDN.TimeDiff(SrY_CzasPrzypomnienia,SrY_TerminOd) + '"/></Reminders>' Else SPACE(100) End,SrY_SerwisantTyp,SrY_SerwisantID,SrZ_NumerPelny,Pod_Kod,0,0  As ZadanieCykliczne,'<ResourceIds><ResourceId Type="System.String" Value="' + (CASE SrY_SerwisantTyp WHEN 8 THEN CASE SrY_SerwisantID WHEN 0 THEN '' WHEN 1 THEN 'ADMIN' WHEN 12 THEN 'BARTEK' WHEN 3 THEN 'DAREK' WHEN 10 THEN 'GOSIA' WHEN 14 THEN 'JAREK' WHEN 5 THEN 'KRZYSZTOF' WHEN 4 THEN 'LESZEK' WHEN 8 THEN 'LIDIA' WHEN 6 THEN 'MACIEJ' WHEN 9 THEN 'MAGDA' WHEN 11 THEN 'MAGDALENA' WHEN 7 THEN 'MAŁGORZATA' WHEN 13 THEN 'ONE_DOD' END ELSE IsNull((SELECT TOP 1 PRI_Kod FROM cdn.PracIdx WHERE PRI_PraID=SrY_SerwisantID), '') END) + '" /></ResourceIds>' FROM CDN.SrsCzynnosci JOIN cdn.SrsZlecenia on SrY_SrZId = SrZ_SrZId JOIN CDN.PodmiotyView ON Pod_PodId = SrZ_PodmiotId AND Pod_PodmiotTyp = SrZ_PodmiotTyp WHERE SrZ_Bufor > -1 AND SrY_Realizacja = 2 AND SrY_RezerwujCzas = 1 UNION ALL SELECT CASE WHEN DnV_Typ=2 THEN 751 ELSE 750 END,CASE DnE_OpeID WHEN 0 THEN '' WHEN 1 THEN 'ADMIN' WHEN 12 THEN 'BARTEK' WHEN 3 THEN 'DAREK' WHEN 10 THEN 'GOSIA' WHEN 14 THEN 'JAREK' WHEN 5 THEN 'KRZYSZTOF' WHEN 4 THEN 'LESZEK' WHEN 8 THEN 'LIDIA' WHEN 6 THEN 'MACIEJ' WHEN 9 THEN 'MAGDA' WHEN 11 THEN 'MAGDALENA' WHEN 7 THEN 'MAŁGORZATA' WHEN 13 THEN 'ONE_DOD' END,CASE When DnE_Wykonany=0 Then 2 ELSE 1 END,0,DnE_DnPrID,Convert (VarChar(50),  DnE_Nazwa),Convert (VarChar(100), DnE_Komentarz),DnE_TerminOd,DnE_TerminDo,Case When DnE_Wykonany=1 Then 7 Else 6 End,Case When DnE_Przypomnienie=1 Then '<Reminders><Reminder AlertTime="' + Convert(VarChar(20),DnE_CzasPrzypomnienia) + '" TimeBeforeStart="' + CDN.TimeDiff(DnE_CzasPrzypomnienia,DnE_TerminOd) + '"/></Reminders>' Else SPACE(100) End,8,DnE_OpeID,DnV_NumerPelny,IsNull((SELECT TOP 1 POD_Kod  FROM CDN.DokPodmioty JOIN cdn.PodmiotyView ON Pod_PodmiotTyp=DoP_PodmiotTyp AND Pod_PodId=DoP_PodmiotID WHERE DnV_Typ=1 AND DoP_DoNID = DnV_DoNId),''),0,0 As ZadanieCykliczne,'<ResourceIds><ResourceId Type="System.String" Value="' + (CASE DnE_OpeID WHEN 0 THEN '' WHEN 1 THEN 'ADMIN' WHEN 12 THEN 'BARTEK' WHEN 3 THEN 'DAREK' WHEN 10 THEN 'GOSIA' WHEN 14 THEN 'JAREK' WHEN 5 THEN 'KRZYSZTOF' WHEN 4 THEN 'LESZEK' WHEN 8 THEN 'LIDIA' WHEN 6 THEN 'MACIEJ' WHEN 9 THEN 'MAGDA' WHEN 11 THEN 'MAGDALENA' WHEN 7 THEN 'MAŁGORZATA' WHEN 13 THEN 'ONE_DOD' END) + '" /></ResourceIds>' FROM CDN.DokNagProcesEtapyView JOIN cdn.DokNagEtapyView on DnE_Typ = DnPr_Typ and DnE_DnPrID = DnPr_DnPrId JOIN cdn.DokNagView  on DnPr_Typ = DnV_Typ and DnPr_DoNId = DnV_DoNId WHERE DnE_RezerwujCzas = 1 UNION ALL SELECT 24400,PRA_Kod, 1,0,PnB_PnBId,Convert (VarChar(50),  TNB_Nazwa),Convert (VarChar(100), ''),PNB_OkresOd,dateadd(second, -1, dateadd(day, datediff(day, 0, PNB_OkresDo)+1, 0)),5,SPACE(100),3,PRA_PraId,SPACE(20),PRA_Kod,0,0 As ZadanieCykliczne,'<ResourceIds><ResourceId Type="System.String" Value="' + (PRA_Kod) + '" /></ResourceIds>' FROM CDN.PracKod JOIN cdn.PracNieobec on PRA_PraId = PNB_PraId JOIN cdn.TypNieobec on PNB_TnbId = TNB_TnbId WHERE (PNB_Tryb=0 OR PNB_Tryb=2)